#!/usr/bin/env python3
"""П-39 r1: генератор docs/research/P-39-params-2026-11-07.csv (общие правила + ОДИН вариант на строку). Только stdlib, <1 с.
Запуск из этой папки:  python make_params.py   (пишет ../P-39-params-2026-11-07.csv, печатает число строк по семействам).
Формат как у P-38-params-*.csv: key, value, status, when, source. Строки `v_<ID>` — варианты поиска; значение — полная спецификация (все поля, значения по умолчанию явно).
Числа протокола — docs/research/P-39-convergence-explore-2026-11-07.md; здесь они продублированы машиночитаемо. Правка params после старта поиска запрещена (отступление — запись в §13 протокола).
"""
import csv
import os
import sys
from collections import Counter

sys.stdout.reconfigure(encoding="utf-8")
PROTO = "docs/research/P-39-convergence-explore-2026-11-07.md"
WHEN = "P-39 r1 07.11"
ASG = "назначено CEO без Судьи, подтвердить"
SRC = "из источника"
MEAS = "измерено по 35 суткам (пост hoc), подтвердить"
CAL = "калибровка по формированию 2472…2478, правило §5.4; заполняется addendum ДО поиска"
DER = "производное"

EXCH = ("binance", "bybit", "okx", "bingx", "bitget", "kraken", "aster", "lighter")
BASES = {"B1": dict(T=1440, q5="on"), "B2": dict(T=120, q5="off")}
rows = []


def g(key, value, status, source):
    rows.append((key, value, status, WHEN, source))


def spec(vid, fam, base, **kw):
    b = BASES.get(base, BASES["B2"])
    d = dict(fam=fam, base=base, th=40, k=3, p=3, T=b["T"], s0="none", lam=320, ecap="base", q5=b["q5"], ffilt="none", sgap="none", excl_ex="none",
             shortban="none", terc="all", out="none", delay=1, cls="crypto", gate="no", stage=1)
    d.update(kw)
    return f"id={vid}; " + "; ".join(f"{k}={v}" for k, v in d.items())


variants = []      # (id, fam, spec, status, source)


def v(vid, fam, base, status, source, **kw):
    variants.append((vid, fam, spec(vid, fam, base, **kw), status, source))


# REF
for b in BASES:
    v(f"REF-{b}", "REF", b, SRC, f"{PROTO} §5.1; П-38 r3 R3.2 ({'V1' if b == 'B1' else 'V2'})")
# A: стоп
for b in BASES:
    for lam in (320, 640, 960, "inf"):
        for T in (120, 360, 1440):
            if lam == 320 and T == BASES[b]["T"]:
                continue
            v(f"A-{b}-L{lam}-T{T}", "A", b, ASG + " (Λ 640 и 960 — поручение CEO; T — сетка П-38)", f"{PROTO} §6.A [P39-N03]", lam=lam, T=T)
    for T in (120, 360, 1440):
        v(f"A-{b}-S0-T{T}", "A", b, ASG + " (s0 = 2 — сетка П-38)", f"{PROTO} §6.A", s0=2, lam="inf", T=T)
    for lam in (640, "inf"):
        v(f"A-{b}-E640-L{lam}", "A", b, ASG, f"{PROTO} §6.A [P39-N04]", ecap=640, lam=lam)
# B: фандинг
for b in BASES:
    for h in ("T", "q90"):
        for phi in ("0", "0.25", "0.5", "1.0"):
            v(f"B-{b}-h{h}-phi{phi}", "B", b, ASG + " (phi, h — титруются сеткой; h_q90 измерено)", f"{PROTO} §6.B [P39-N05, N06]", ffilt=f"phi:{phi}/h:{h}")
# C: структурный разрыв
for b in BASES:
    for n in (1, 3, 7):
        for q in ("0.90", "0.95", "0.99"):
            v(f"C-{b}-n{n}-q{q[2:]}", "C", b, ASG + " (n — поручение CEO; q — сетка; beta измеряется)", f"{PROTO} §6.C [P39-N07, N08]", sgap=f"n:{n}/q:{q}")
# D: исполнение (задержка)
for b in BASES:
    for d in (0, 2, 5):
        v(f"D-{b}-d{d}", "D", b, ASG + " (задержки 0/+2/+5 — поручение CEO)" + ("; d0 — справка, вне ранжирования" if d == 0 else ""), f"{PROTO} §6.D [P39-N09]", delay=d)
# E: подмножества
for b in BASES:
    for ex in EXCH:
        v(f"E-{b}-no-{ex}", "E", b, ASG, f"{PROTO} §6.E [P39-N11]", excl_ex=ex)
    v(f"E-{b}-noshort-bybit", "E", b, ASG, f"{PROTO} §6.E [P39-N11]", shortban="bybit")
    for t in (1, 2, 3):
        v(f"E-{b}-terc{t}", "E", b, ASG, f"{PROTO} §6.E [P39-N11]", terc=t)
    for o in ("S", "L"):
        v(f"E-{b}-out{o}", "E", b, ASG, f"{PROTO} §6.E [P39-N11]", out=o)
    for q in ("0.95", "0.99"):
        v(f"E-{b}-ox{q[2:]}", "E", b, ASG + " (gamma измеряется)", f"{PROTO} §6.E [P39-N11]", out=f"OX:{q}")
    for gt in ("plus", "only"):
        v(f"E-{b}-gate-{gt}", "E", b, ASG + " (Gate — описательно)", f"{PROTO} §6.E", gate=gt)
v("E-eq-own", "E", "B2", ASG + " (класс eq: числа формирования П-38)", f"{PROTO} §6.E; П-38 R3.1", cls="eq", th=40, k=5, p=1, T=120, s0=2, lam="class", q5="on")
v("E-eq-B2", "E", "B2", ASG + " (класс eq, комбинация B2, Q5 включён)", f"{PROTO} §6.E", cls="eq", th=40, k=3, p=3, T=120, s0="none", lam="class", q5="on")
# F: пороги
for b in BASES:
    for th in (25.2, 40, 80, 160):
        for k in (3, 5, 8):
            for p in (1, 3):
                if (th, k, p) == (40, 3, 3):
                    continue
                v(f"F-{b}-th{th}-k{k}-p{p}", "F", b, SRC + " (сетка П-38)", f"{PROTO} §6.F [P39-N12]", th=th, k=k, p=p)

cnt = Counter(x[1] for x in variants)
want = {"REF": 2, "A": 32, "B": 16, "C": 18, "D": 6, "E": 38, "F": 46}
assert dict(cnt) == want, (dict(cnt), want)
assert len({x[0] for x in variants}) == len(variants)
total = len(variants)
assert total == 158

# ---------------------------------------------------------------- общие правила
g("protocol", "P-39 r1", SRC, PROTO)
g("ticket", "TK-493", SRC, ".claude/tickets/TK-493.md")
g("params_state", "G0 П-39: правила и ОДИН вариант на строку (строки v_*); записано ДО кода поиска и ДО любого запуска в режиме поиска; значения со статусом «калибровка по формированию» заполняются addendum docs/research/P-39-params-calib-<дата>.csv ДО поиска; после старта поиска params не правятся", SRC, PROTO + " шапка")
g("owner_basis", "владелец 07.11 (дословно): «У меня стойкое ощущение что ты специально методологически делаешь так чтобы невозможно было найти альфу» · «Ты идиот?» (когда было предложено поиск и спрошено «да»); В-91: «с протоколом не жести тк нам надо найти, а не подогнать». Номер В-## не присвоен (CEO)", SRC, PROTO + " шапка")
g("kind", "C2 схождения: ПОИСК (не подтверждение) на 35 сутках 01.10–04.11; подтверждение — только на новых сутках >= 2500", ASG, PROTO + " §0")
g("search_vs_confirm", "поиск: сутки 2465..2499 читаются свободно, 158 + <= 34 вариантов, нет статусов и нет Холма как условия, описательное ранжирование; подтверждение: сутки >= 2500, <= 3 варианта, статусы по образцу R3.3, Холм на M_подтв, НОВЫЙ токен", ASG, PROTO + " §0")
g("banner_text", "ПОИСК П-39 — НЕ ПОДТВЕРЖДЕНИЕ: сутки 2465…2499 (01.10–04.11), выбрано по 35 суткам, пост hoc; слов «подтверждено» нет", ASG, PROTO + " §3")
g("banner_rule", "первая строка КАЖДОГО выходного файла поиска (CSV — «# …», JSON — ключ _banner, txt/md — первая строка); проверка скриптом (G-X-5 д)", ASG, PROTO + " §3, §11.2")
g("day_index_origin", "сутки считаются от 2020-01-01 UTC (как П-38): 2465 = 01.10.2026, 2479 = 15.10, 2499 = 04.11, 2500 = 05.11", SRC, "P-38 params day_index_origin")
