g("untouched_paths", "не менять и не удалять: ~/xdl9/c2/window, ~/xdl9/c2/out*, ~/xdl9/c2g/out*, window_reads.log; go_window.token нет (сожжён) — поиск его не создаёт и не читает; conv_window.py и conv_guard.py не меняются в коммитах поиска", ASG, PROTO + " §3, §11")
g("resources", "только Deck: systemd-run --user, nice -n 10, потоки по префлайту памяти (не более 8), numpy ~/xdl9/venv/bin/python (scipy нет); ПК — текст и stdlib <= 2 с; диск /home свободно ~14 ГБ: префлайт >= 10 ГБ, кэш ~5,9 ГБ удалять по завершении, выходы поиска <= 5 ГБ", ASG, PROTO + " §3")
# метрика
g("metric_y_d", "y_d = [сумма net закрытых сделок суток + MTM на конце] / число активных пар-суток; сутки без активных пар в ряд не входят", SRC, "P-38 §7.4, §9.2")
g("y_d_denominator", "активные пары-сутки базы на универсуме варианта; фильтры входа знаменатель НЕ уменьшают; подмножества пар (без биржи X, терцили, Gate, eq) — сужают по построению; рядом печатается сумма net / число суток", ASG, PROTO + " §4 [P39-N02]")
